import torch

def train_accumulated(model, batches, optimizer, criterion, accum_steps=4):
    optimizer.zero_grad()
    for step, (x, y) in enumerate(batches, 1):
        loss = criterion(model(x), y) / accum_steps
        loss.backward()
        if step % accum_steps == 0:
            torch.nn.utils.clip_grad_norm_(model.parameters(), 1.0)
            optimizer.step()
            optimizer.zero_grad()

from collections import deque

def topological_sort(graph: dict) -> list:
    in_degree = {u: 0 for u in graph}
    for u, neighbors in graph.items():
        for v in neighbors:
            in_degree[v] = in_degree.get(v, 0) + 1
    queue = deque([u for u, deg in in_degree.items() if deg == 0])
    order = []
    while queue:
        u = queue.popleft()
        order.append(u)
        for v in graph.get(u, []):
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)
    if len(order) != len(in_degree):
        raise ValueError('Cycle detected in dependency graph')
    return order

import torch
import torch.nn as nn
import torch.nn.functional as F

class SwiGLU(nn.Module):
    def __init__(self, dim: int, hidden_dim: int):
        super().__init__()
        self.w_gate = nn.Linear(dim, hidden_dim)
        self.w_val = nn.Linear(dim, hidden_dim)
        self.w_out = nn.Linear(hidden_dim, dim)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.w_out(F.silu(self.w_gate(x)) * self.w_val(x))
